INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'shifa-polyclinic-case-1', 'NHRA Accredited Day-Surgery Wing', 'اعتماد جناح جراحة اليوم الواحد بالعيادة', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Zinj with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Zinj وفق أعلى معايير الجودة والالتزام.', 90, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://alshifaclinic.bh/work/shifa-polyclinic-case-1', 'Zinj, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'shifa-polyclinic-2026-outlook', 'Al-Shifa Clinic 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — عيادة الشفاء', 'Key operational benchmarks, real metrics, and 2026 guidance from Al-Shifa Clinic in Zinj.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من عيادة الشفاء في Zinj.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"NHRA-licensed outpatient medical center offering family medicine, dental, dermatology, and diagnostic laboratory services. Focusing on Comprehensive Family Health Checkup, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مركز طبي تخصصي مرخص يقدم خدمات طب الأسرة والأسنان والجلدية والمختبرات التشخيصية. من خلال خدمة فحص صحي شامل للأسرة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>NHRA-licensed outpatient medical center offering family medicine, dental, dermatology, and diagnostic laboratory services.</p><p>Focusing on <strong>Comprehensive Family Health Checkup</strong>, our Zinj specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مركز طبي تخصصي مرخص يقدم خدمات طب الأسرة والأسنان والجلدية والمختبرات التشخيصية.</p><p>من خلال خدمة <strong>فحص صحي شامل للأسرة</strong>، يعمل فريقنا في Zinj على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Al-Shifa Clinic 2026 GCC Market Outlook & Benchmarks | Al-Shifa Clinic', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — عيادة الشفاء | عيادة الشفاء', 'Executive guide by Al-Shifa Clinic covering Comprehensive Family Health Checkup benchmarks in Bahrain.', 'دليل تنفيذي من عيادة الشفاء حول معايير فحص صحي شامل للأسرة في البحرين.', 'Insights', '{"healthcare","insights","Zinj","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Al-Shifa Clinic initiate a Comprehensive Family Health Checkup engagement?', 'كم يستغرق بدء تنفيذ خدمة فحص صحي شامل للأسرة لدى عيادة الشفاء؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Zinj.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Zinj.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'shifa-polyclinic-case-2', 'National Sports Federation Physio Partner', 'شريك التأهيل الطبي للاتحادات الرياضية', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Zinj with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Zinj وفق أعلى معايير الجودة والالتزام.', 105, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://alshifaclinic.bh/work/shifa-polyclinic-case-2', 'Zinj, Bahrain') ON CONFLICT (id) DO NOTHING;
