INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"Al-Shifa Specialist Polyclinic W.L.L.","nameAr":"مجمع الشفاء التخصصي الطبي ذ.م.م","shortEn":"Al-Shifa Clinic","shortAr":"عيادة الشفاء","taglineEn":"Multi-Specialty Outpatient Care & Diagnostics","taglineAr":"رعاية تخصصية شاملة وتشخيص مخبري دقيق","aboutEn":"NHRA-licensed outpatient medical center offering family medicine, dental, dermatology, and diagnostic laboratory services.","aboutAr":"مركز طبي تخصصي مرخص يقدم خدمات طب الأسرة والأسنان والجلدية والمختبرات التشخيصية."},"hero":{"titleEn":"Al-Shifa Clinic — Multi-Specialty Outpatient Care & Diagnostics","titleAr":"عيادة الشفاء — رعاية تخصصية شاملة وتشخيص مخبري دقيق","ctaLabelEn":"Explore Al-Shifa Clinic","ctaLabelAr":"استكشف عيادة الشفاء"},"banners":[{"id":"hero-1","title_en":"Al-Shifa Clinic: Comprehensive Family Health Checkup","title_ar":"عيادة الشفاء: فحص صحي شامل للأسرة","subtitle_en":"Multi-Specialty Outpatient Care & Diagnostics","subtitle_ar":"رعاية تخصصية شاملة وتشخيص مخبري دقيق","media_type":"image","media_url":"/api/files/media/banners/banner-01.png","poster_url":"/api/files/media/banners/banner-01.png","display_order":1,"is_active":true,"cta_label_en":"Request Proposal","cta_label_ar":"اطلب عرض سعر","cta_link":"/contact"},{"id":"hero-2","title_en":"Al-Shifa Clinic: Digital Dental Diagnostics & Cleaning","title_ar":"عيادة الشفاء: فحص وتنظيف الأسنان الرقمي","subtitle_en":"Multi-Specialty Outpatient Care & Diagnostics","subtitle_ar":"رعاية تخصصية شاملة وتشخيص مخبري دقيق","media_type":"image","media_url":"/api/files/media/banners/banner-02.png","poster_url":"/api/files/media/banners/banner-02.png","display_order":2,"is_active":true,"cta_label_en":"Explore Our Work","cta_label_ar":"استعرض أعمالنا","cta_link":"/work"},{"id":"hero-3","title_en":"Al-Shifa Clinic: Comprehensive Executive Health Screening","title_ar":"عيادة الشفاء: باقة الفحص الطبي الشامل للتنفيذيين","subtitle_